UPDATE "GiftItem" SET "universe" = 'CELEBRATE'::"GiftUniverse", "collection" = 'classics', "occasionTags" = ARRAY['appreciation']::TEXT[], "rarity" = 'STANDARD'::"GiftRarity", "editionSize" = NULL, "availableFrom" = NULL, "availableUntil" = NULL WHERE "slug" = 'wave';
